CREATE TABLE IF NOT EXISTS cloud_revision(id INTEGER PRIMARY KEY, version INTEGER NOT NULL);
INSERT OR IGNORE INTO cloud_revision(id,version) VALUES(1,0);
ALTER TABLE businesses ADD COLUMN email TEXT NOT NULL DEFAULT '';
ALTER TABLE products ADD COLUMN current_cost INTEGER NOT NULL DEFAULT 0;
ALTER TABLE lots ADD COLUMN original_qty INTEGER NOT NULL DEFAULT 0;
ALTER TABLE lots ADD COLUMN purchase_id INTEGER;
ALTER TABLE lots ADD COLUMN status TEXT NOT NULL DEFAULT 'Activo';
ALTER TABLE stock_moves ADD COLUMN cost INTEGER NOT NULL DEFAULT 0;
ALTER TABLE stock_moves ADD COLUMN cost_basis INTEGER NOT NULL DEFAULT 1000;
ALTER TABLE stock_moves ADD COLUMN balance_after INTEGER NOT NULL DEFAULT 0;
ALTER TABLE stock_moves ADD COLUMN note TEXT NOT NULL DEFAULT '';
CREATE TABLE IF NOT EXISTS receivables(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, sale_id INTEGER NOT NULL UNIQUE, created TEXT NOT NULL, original_amount INTEGER NOT NULL, paid_amount INTEGER NOT NULL DEFAULT 0, returned_amount INTEGER NOT NULL DEFAULT 0, balance INTEGER NOT NULL, status TEXT NOT NULL);
CREATE INDEX IF NOT EXISTS idx_receivables_customer ON receivables(business_id,customer_id,status);
CREATE TABLE IF NOT EXISTS receivable_moves(id INTEGER PRIMARY KEY, receivable_id INTEGER NOT NULL, business_id INTEGER NOT NULL, customer_id INTEGER NOT NULL, sale_id INTEGER NOT NULL, payment_id INTEGER, created TEXT NOT NULL, kind TEXT NOT NULL, amount INTEGER NOT NULL, balance_after INTEGER NOT NULL, user_id INTEGER NOT NULL, note TEXT NOT NULL DEFAULT '', request_id TEXT UNIQUE);
CREATE TABLE IF NOT EXISTS purchases(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL, number INTEGER NOT NULL, supplier TEXT NOT NULL, reference TEXT NOT NULL DEFAULT '', created TEXT NOT NULL, user_id INTEGER NOT NULL, total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Activa', note TEXT NOT NULL DEFAULT '', request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS purchase_lines(id INTEGER PRIMARY KEY, purchase_id INTEGER NOT NULL, product_id INTEGER NOT NULL, lot_id INTEGER NOT NULL, qty INTEGER NOT NULL, returned_qty INTEGER NOT NULL DEFAULT 0, cost INTEGER NOT NULL, cost_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS purchase_returns(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL, number INTEGER NOT NULL, purchase_id INTEGER, supplier TEXT NOT NULL, created TEXT NOT NULL, user_id INTEGER NOT NULL, reason TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', total INTEGER NOT NULL, status TEXT NOT NULL DEFAULT 'Registrada', manual INTEGER NOT NULL DEFAULT 0, request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS purchase_return_lines(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL, purchase_line_id INTEGER, product_id INTEGER NOT NULL, lot_id INTEGER, qty INTEGER NOT NULL, cost INTEGER NOT NULL, cost_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS sales_returns(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL, number INTEGER NOT NULL, sale_id INTEGER, customer_id INTEGER, cash_id INTEGER NOT NULL, created TEXT NOT NULL, user_id INTEGER NOT NULL, reason TEXT NOT NULL, note TEXT NOT NULL DEFAULT '', refund_method TEXT NOT NULL, total INTEGER NOT NULL, debt_reduction INTEGER NOT NULL DEFAULT 0, stock_return INTEGER NOT NULL DEFAULT 1, request_id TEXT NOT NULL, UNIQUE(business_id,number), UNIQUE(business_id,request_id));
CREATE TABLE IF NOT EXISTS sales_return_lines(id INTEGER PRIMARY KEY, return_id INTEGER NOT NULL, sale_line_id INTEGER, product_id INTEGER NOT NULL, qty INTEGER NOT NULL, price INTEGER NOT NULL, price_basis INTEGER NOT NULL DEFAULT 1000, total INTEGER NOT NULL, cost INTEGER NOT NULL, restock INTEGER NOT NULL DEFAULT 1);
CREATE TABLE IF NOT EXISTS document_emails(id INTEGER PRIMARY KEY, business_id INTEGER NOT NULL, kind TEXT NOT NULL, document_id INTEGER NOT NULL, recipient TEXT NOT NULL, created TEXT NOT NULL, status TEXT NOT NULL DEFAULT 'pending', error TEXT NOT NULL DEFAULT '');
